
const APP_VERSION = 1;
const DEFAULT_CATEGORIES = [
  {id:'food',name:'Food & dining',icon:'◉',kind:'expense'}, {id:'travel',name:'Travel',icon:'⌁',kind:'expense'},
  {id:'bills',name:'Bills',icon:'⌁',kind:'expense'}, {id:'shopping',name:'Shopping',icon:'◇',kind:'expense'},
  {id:'health',name:'Health',icon:'✚',kind:'expense'}, {id:'fun',name:'Leisure',icon:'✦',kind:'expense'},
  {id:'salary',name:'Salary',icon:'↑',kind:'income'}, {id:'freelance',name:'Freelance',icon:'✎',kind:'income'},
  {id:'other',name:'Other',icon:'•',kind:'both'}
];
const freshState = () => ({version:APP_VERSION, profile:null, accounts:[], categories:DEFAULT_CATEGORIES.map(x=>({...x})), transactions:[], budget:{monthlyLimit:0,categoryLimits:{}}, debts:[], goals:[], reminders:[], settings:{theme:'dark',warningThreshold:80,budgetWarnings:true,billAlerts:true,positiveAlerts:true,debtAlerts:true,weeklySummary:false,quietStart:'22:00',quietEnd:'07:00'}, sampleData:false});
const storage = {
  db:null,
  async open(){
    if(this.db) return this.db;
    return new Promise((resolve,reject)=>{const req=indexedDB.open('pocketwise-local',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>{this.db=req.result;resolve(this.db)};req.onerror=()=>reject(req.error)});
  },
  async load(){
    try { const db=await this.open(); return await new Promise((resolve,reject)=>{const r=db.transaction('workspace','readonly').objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result||freshState());r.onerror=()=>reject(r.error)}); }
    catch { try{return JSON.parse(localStorage.getItem('pocketwise-fallback')||'null')||freshState()}catch{return freshState()} }
  },
  async save(value){
    const clone=JSON.parse(JSON.stringify(value));
    try { const db=await this.open(); await new Promise((resolve,reject)=>{const r=db.transaction('workspace','readwrite').objectStore('workspace').put(clone,'state');r.onsuccess=resolve;r.onerror=()=>reject(r.error)}); }
    catch { localStorage.setItem('pocketwise-fallback',JSON.stringify(clone)); }
  }
};
let state=freshState();
let ui={page:'home',activityType:'all',activityRange:'all',activitySearch:'',chartPeriod:'month',assistant:[]};
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const id = (prefix='id') => prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const num = value => Number.parseFloat(value)||0;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => {const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const localDate = s => {const [y,m,d]=String(s||today()).split('-').map(Number);return new Date(y,m-1,d,12)};
const iso = d => d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const monthKey = (date=today()) => String(date).slice(0,7);
const inMonth = (date,key=monthKey()) => String(date).slice(0,7)===key;
const dateLabel = d => new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:localDate(d).getFullYear()!==new Date().getFullYear()?'numeric':undefined}).format(localDate(d));
const money = value => state.profile?.hideBalances ? '••••••' : new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(value)||0);
const rawMoney = value => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(value)||0);
const profile = () => state.profile||{name:'there',avatar:'#735ef7'};
const account = id => state.accounts.find(a=>a.id===id);
const accountName = id => account(id)?.name||'Unassigned account';
const category = id => state.categories.find(c=>c.id===id)||{name:'Uncategorised',icon:'•'};
const txTitle = tx => tx.activityName || category(tx.categoryId).name || typeName(tx.type);
const typeName = type => ({expense:'Expense',income:'Income',transfer:'Transfer',refund:'Refund',debtLent:'Money lent',debtBorrowed:'Money borrowed',debtReceived:'Debt repayment received',debtPaid:'Debt repayment made'})[type]||type;
const isIncome = tx => ['income','refund','debtBorrowed','debtReceived'].includes(tx.type);
const isExpense = tx => ['expense','debtLent','debtPaid'].includes(tx.type);
function applyShape(){
  const base=freshState(); state={...base,...state,budget:{...base.budget,...(state.budget||{})},settings:{...base.settings,...(state.settings||{})}};
  for(const k of ['accounts','categories','transactions','debts','goals','reminders']) if(!Array.isArray(state[k])) state[k]=base[k];
  if(!state.categories.length) state.categories=base.categories;
}
async function persist(){ await storage.save(state); }
async function mutate(fn,notice){ fn(); await persist(); render(); if(notice) toast(notice,'success'); }
function accountBalance(accountId){
  const acc=account(accountId); if(!acc) return 0; let amount=num(acc.openingBalance);
  for(const tx of state.transactions){ const v=num(tx.amount); if(tx.type==='transfer'){if(tx.sourceAccountId===accountId)amount-=v;if(tx.destinationAccountId===accountId)amount+=v;continue;}
    if(tx.accountId!==accountId) continue;
    if(['income','refund','debtBorrowed','debtReceived'].includes(tx.type))amount+=v;
    if(['expense','debtLent','debtPaid'].includes(tx.type))amount-=v;
  } return amount;
}
function totalBalance(){return state.accounts.reduce((sum,a)=>sum+accountBalance(a.id),0)}
function monthTransactions(key=monthKey()){return state.transactions.filter(t=>inMonth(t.date,key));}
function stats(key=monthKey()){
  const txs=monthTransactions(key); let income=0,expenses=0,refunds=0;
  for(const tx of txs){if(tx.type==='income')income+=num(tx.amount);if(tx.type==='expense')expenses+=num(tx.amount);if(tx.type==='refund')refunds+=num(tx.amount)}
  const spent=Math.max(0,expenses-refunds); const commitments=upcomingCommitments(key); const limit=num(state.budget.monthlyLimit); return {income,expenses:spent,refunds,net:income-spent,limit,remaining:Math.max(0,limit-spent),percentage:limit?Math.min(100,spent/limit*100):0,available:Math.max(0,totalBalance()-commitments),commitments};
}
function debtOutstanding(debt){return Math.max(0,num(debt.amount)-state.transactions.filter(t=>t.debtId===debt.id&&['debtReceived','debtPaid'].includes(t.type)).reduce((s,t)=>s+num(t.amount),0))}
function debtsSummary(){let lent=0,borrowed=0;state.debts.forEach(d=>{if(d.direction==='lent')lent+=debtOutstanding(d);else borrowed+=debtOutstanding(d)});return{lent,borrowed}}
function goalProgress(goal){const saved=(goal.contributions||[]).reduce((s,c)=>s+num(c.amount),0)+num(goal.initialAmount);return{saved,target:num(goal.target),percent:num(goal.target)?Math.min(100,saved/num(goal.target)*100):0}}
function addMonthsSafe(date,months){const d=localDate(date);const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return iso(d)}
function nextDue(reminder,from=today()){
  let due=String(reminder.date); if(due>=from) return due; let guard=0;
  while(due<from&&guard++<500){if(reminder.recurrence==='weekly'){const d=localDate(due);d.setDate(d.getDate()+7);due=iso(d)}else if(reminder.recurrence==='monthly')due=addMonthsSafe(due,1);else if(reminder.recurrence==='yearly')due=addMonthsSafe(due,12);else return due}return due;
}
function upcomingCommitments(key=monthKey()){return state.reminders.reduce((sum,r)=>nextDue(r).startsWith(key)?sum+num(r.amount):sum,0)}
function categorySpend(key=monthKey()) {const map={};for(const tx of monthTransactions(key)){if(tx.type==='expense')map[tx.categoryId]=(map[tx.categoryId]||0)+num(tx.amount);if(tx.type==='refund')map[tx.categoryId]=(map[tx.categoryId]||0)-num(tx.amount)}return Object.entries(map).map(([categoryId,amount])=>({categoryId,amount:Math.max(0,amount)})).sort((a,b)=>b.amount-a.amount)}
function alerts(){ const s=stats();const out=[];if(s.limit&&s.percentage>=100)out.push({icon:'!',title:'Monthly budget exceeded',copy:'Recorded spending is '+rawMoney(s.expenses)+' against a '+rawMoney(s.limit)+' limit.'});else if(s.limit&&s.percentage>=num(state.settings.warningThreshold))out.push({icon:'!',title:'Budget check-in',copy:'You have used '+Math.round(s.percentage)+'% of this month’s spending limit.'});
  const soon=state.reminders.map(r=>({...r,due:nextDue(r)})).filter(r=>r.due>=today()&&r.due<=iso(new Date(Date.now()+7*86400000))).sort((a,b)=>a.due.localeCompare(b.due))[0];if(soon)out.push({icon:'◷',title:'Upcoming: '+soon.description,copy:rawMoney(soon.amount)+' due '+dateLabel(soon.due)+'.'});
  const overdue=state.debts.find(d=>d.expectedDate&&d.expectedDate<today()&&debtOutstanding(d)>0);if(overdue)out.push({icon:'◌',title:'Debt follow-up',copy:overdue.person+' has '+rawMoney(debtOutstanding(overdue))+' outstanding.'});
  const completed=state.goals.find(g=>goalProgress(g).percent>=100);if(completed)out.push({icon:'★',title:'Goal complete',copy:'“'+completed.name+'” has reached its target.'});return out;
}
function periodTransactions(period){const now=localDate(today());let from;if(period==='week'){from=new Date(now);from.setDate(now.getDate()-6)}else if(period==='year'){from=new Date(now.getFullYear(),0,1)}else{from=new Date(now.getFullYear(),now.getMonth(),1)}return state.transactions.filter(t=>t.type==='expense'&&localDate(t.date)>=from&&localDate(t.date)<=now)}
function graphData(period){const now=localDate(today());let buckets=[];if(period==='week'){for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(now.getDate()-i);buckets.push({key:iso(d),label:new Intl.DateTimeFormat('en-IN',{weekday:'narrow'}).format(d),value:0})}}else if(period==='year'){for(let i=0;i<12;i++)buckets.push({key:now.getFullYear()+'-'+String(i+1).padStart(2,'0'),label:new Intl.DateTimeFormat('en-IN',{month:'short'}).format(new Date(now.getFullYear(),i,1)),value:0})}else{const days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();for(let i=1;i<=days;i++)buckets.push({key:now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(i).padStart(2,'0'),label:String(i),value:0})}
  for(const tx of state.transactions.filter(t=>t.type==='expense')){const key=period==='year'?String(tx.date).slice(0,7):String(tx.date);const b=buckets.find(x=>x.key===key);if(b)b.value+=num(tx.amount)}return buckets;
}
function navItem(page,icon,label){return '<button class="nav-item '+(ui.page===page?'active':'')+'" data-page="'+page+'"><span class="nav-icon" aria-hidden="true">'+icon+'</span><span>'+label+'</span></button>'}
function header(title,sub){const p=profile();return `<header class="topbar"><div><p class="greeting">${sub||'Your private finance space'}</p><strong>${title||'Good '+(new Date().getHours()<12?'morning':'day')+', '+esc(p.name)}</strong></div><div class="top-controls"><button class="icon-button" data-action="quick-add" aria-label="Add transaction">＋</button><button class="icon-button" data-action="toggle-hide" aria-label="Hide or show amounts">${p.hideBalances?'◉':'◌'}</button><button class="avatar" style="background:${p.avatar}" data-page="settings" aria-label="Open settings">${esc(p.name||'?').slice(0,1).toUpperCase()}</button></div></header>`}
function layout(content){return `<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">◒</span>Pocketwise</div><nav class="nav-list" aria-label="Primary navigation">${navItem('home','⌂','Home')}${navItem('activity','≡','Activity')}${navItem('insights','◔','Insights')}${navItem('settings','⚙','Settings')}</nav><button class="secondary-button" data-page="assistant">✦ Ask Pocketwise</button><div class="local-note"><strong>Private by design</strong>Everything is kept in this browser’s local storage. Export a backup regularly.</div></aside><main class="main">${content}</main><nav class="mobile-nav" aria-label="Primary navigation">${navItem('home','⌂','Home')}${navItem('activity','≡','Activity')}${navItem('insights','◔','Insights')}${navItem('settings','⚙','Settings')}</nav></div>`}
function amountClass(tx){return ['income','refund','debtReceived','debtBorrowed'].includes(tx.type)?'positive':'negative'}
function signedAmount(tx){const plus=['income','refund','debtReceived','debtBorrowed'].includes(tx.type);const transfer=tx.type==='transfer';return (transfer?'↔ ':plus?'+ ':'− ')+money(tx.amount)}
function transactionRow(tx){const c=category(tx.categoryId);const source=tx.type==='transfer'?accountName(tx.sourceAccountId)+' → '+accountName(tx.destinationAccountId):accountName(tx.accountId);return `<article class="transaction" data-action="transaction-detail" data-id="${tx.id}" tabindex="0"><div class="category-dot">${c.icon||'•'}</div><div class="transaction-info"><div class="transaction-title">${esc(txTitle(tx))}</div><div class="transaction-meta">${dateLabel(tx.date)} · ${esc(source)}</div></div><div class="amount ${amountClass(tx)}">${signedAmount(tx)}</div></article>`}
function empty(title,copy,action,label){return `<div class="empty"><strong>${title}</strong>${copy?'<span>'+copy+'</span>':''}${action?'<br><button class="text-button" data-action="'+action+'">'+label+'</button>':''}</div>`}
function chartSVG(data){const values=data.map(x=>x.value),max=Math.max(1,...values),w=520,h=142,pad=12;const pts=data.map((x,i)=>[pad+i*((w-pad*2)/Math.max(1,data.length-1)),h-pad-(x.value/max)*(h-32)]);const path=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');const fill=path+' L '+(pts.at(-1)?.[0]||pad)+' '+(h-pad)+' L '+(pts[0]?.[0]||pad)+' '+(h-pad)+' Z';const last=pts.at(-1)||[pad,h-pad];return `<svg class="line-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Spending pattern"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#957dff" stop-opacity=".42"/><stop offset="1" stop-color="#957dff" stop-opacity="0"/></linearGradient></defs><path class="grid" d="M0 28H${w}M0 70H${w}M0 112H${w}"/><path class="fill" d="${fill}"/><path class="line" d="${path}"/><circle class="dot" cx="${last[0]}" cy="${last[1]}" r="4"/></svg>`}
function pageHome(){const s=stats(),ds=debtsSummary(),recent=[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt).slice(0,5),alertsList=alerts(),chart=graphData(ui.chartPeriod),total=chart.reduce((a,b)=>a+b.value,0),days=new Date().getDate(),monthDays=new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate();const percent=Math.min(100,s.percentage);return `<section class="page">${header('', 'Your financial overview')}<div class="hero"><div class="eyebrow">Total balance <span aria-hidden="true">◌</span></div><div class="balance-row"><div class="balance">${money(totalBalance())}</div><button class="ghost-button" data-action="manage-accounts">Accounts</button></div><div class="hero-stats"><div><div class="stat-label">Income this month</div><div class="stat-value positive">+ ${money(s.income)}</div></div><div><div class="stat-label">Spending this month</div><div class="stat-value negative">− ${money(s.expenses)}</div></div><div><div class="stat-label">Net cash flow</div><div class="stat-value ${s.net>=0?'positive':'negative'}">${s.net>=0?'+ ':''}${money(s.net)}</div></div></div></div><div class="section-head"><h2>Quick actions</h2><button class="text-button" data-page="assistant">Ask Pocketwise ✦</button></div><div class="quick-actions"><button class="action" data-action="add-expense"><span class="action-icon">−</span><span>Add expense</span></button><button class="action" data-action="add-income"><span class="action-icon">＋</span><span>Add income</span></button><button class="action" data-action="transfer"><span class="action-icon">↔</span><span>Transfer</span></button><button class="action" data-action="more-actions"><span class="action-icon">•••</span><span>More</span></button></div><div class="section-head"><h2>This month</h2><button class="text-button" data-action="manage-budget">Manage budget</button></div><div class="cards-scroll"><article class="summary-card primary"><div class="card-top"><span>Available to spend</span><span>◒</span></div><div class="card-amount">${money(s.available)}</div><div class="small-copy">After ${money(s.commitments)} in planned commitments</div></article><article class="summary-card"><div class="card-top"><span>Budget remaining</span><span>${s.limit?'': 'Not set'}</span></div><div class="card-amount">${s.limit?money(s.remaining):'—'}</div><div class="mini-track"><b style="width:${s.limit?percent:0}%"></b></div><div class="small-copy" style="margin-top:9px">${s.limit?Math.round(percent)+'% used of '+money(s.limit):'Set a monthly spending limit'}</div></article><article class="summary-card"><div class="card-top"><span>Debt overview</span><span>◌</span></div><div class="card-amount">${money(ds.lent)}</div><div class="small-copy">Owed to you · You owe ${money(ds.borrowed)}</div></article></div><div class="home-grid"><section class="panel"><div class="chart-toolbar"><h3>Spending pattern</h3><div class="segmented"><button data-action="chart-period" data-period="week" class="${ui.chartPeriod==='week'?'active':''}">Week</button><button data-action="chart-period" data-period="month" class="${ui.chartPeriod==='month'?'active':''}">Month</button><button data-action="chart-period" data-period="year" class="${ui.chartPeriod==='year'?'active':''}">Year</button></div></div><div class="chart-value">${money(total)}</div><div class="chart-sub">Recorded expenses in selected period</div>${chartSVG(chart)}</section><section class="panel"><div class="budget-title"><h3>Monthly budget</h3><button class="text-button" data-action="manage-budget">Edit</button></div><div class="budget-ring" style="--percent:${percent}"><span>${s.limit?Math.round(percent)+'%':'—'}</span></div><div class="budget-foot"><span>Spent<b>${money(s.expenses)}</b></span><span>${s.limit?'Remaining':'Set a limit'}<b>${s.limit?money(s.remaining):'—'}</b></span><span>Day<b>${days+'/'+monthDays}</b></span></div></section></div><div class="home-grid"><section class="panel"><div class="section-head"><h2>Recent activity</h2><button class="text-button" data-page="activity">See all</button></div><div class="list">${recent.length?recent.map(transactionRow).join(''):empty('Nothing recorded yet','Start with an income or expense to see your live overview.','add-expense','Add first expense')}</div></section><section class="panel"><div class="section-head"><h2>At a glance</h2><button class="text-button" data-action="manage-reminders">All reminders</button></div><div class="alerts">${alertsList.length?alertsList.map(a=>`<div class="alert"><span class="alert-icon">${a.icon}</span><div><strong>${esc(a.title)}</strong>${esc(a.copy)}</div></div>`).join(''):empty('You’re all caught up','Set a budget, reminders, or a goal to receive useful local alerts.','more-actions','Set up')}</div></div></div></section>`}
function filteredTransactions(){let list=[...state.transactions];const search=ui.activitySearch.trim().toLowerCase();if(ui.activityType!=='all')list=list.filter(t=>ui.activityType==='debt'?t.type.startsWith('debt'):t.type===ui.activityType);if(ui.activityRange==='month')list=list.filter(t=>inMonth(t.date));if(ui.activityRange==='year')list=list.filter(t=>String(t.date).startsWith(String(new Date().getFullYear())));if(search)list=list.filter(t=>(txTitle(t)+' '+t.date+' '+t.amount+' '+t.note+' '+accountName(t.accountId)+' '+(state.debts.find(d=>d.id===t.debtId)?.person||'')).toLowerCase().includes(search));return list.sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt)}
function pageActivity(){const list=filteredTransactions();return `<section class="page">${header('Activity','Search, review, and manage records')}<div class="activity-layout"><section class="panel"><div class="activity-tools"><input class="field" id="activity-search" value="${esc(ui.activitySearch)}" placeholder="Search activity, note, date or amount" aria-label="Search transactions"><select class="select" id="activity-type" aria-label="Filter transaction type"><option value="all" ${ui.activityType==='all'?'selected':''}>All types</option><option value="expense" ${ui.activityType==='expense'?'selected':''}>Expenses</option><option value="income" ${ui.activityType==='income'?'selected':''}>Income</option><option value="transfer" ${ui.activityType==='transfer'?'selected':''}>Transfers</option><option value="refund" ${ui.activityType==='refund'?'selected':''}>Refunds</option><option value="debt" ${ui.activityType==='debt'?'selected':''}>Debt activity</option></select><button class="primary-button" data-action="quick-add">Add record</button></div><p class="result-note">${list.length} record${list.length===1?'':'s'} found</p><div class="list">${list.length?list.map(transactionRow).join(''):empty('No matching activity','Try changing a filter or add a new record.','quick-add','Add transaction')}</div></section><aside class="panel filter-card"><h3>Filters</h3><label for="activity-range">Date range</label><select class="select" id="activity-range"><option value="all" ${ui.activityRange==='all'?'selected':''}>All time</option><option value="month" ${ui.activityRange==='month'?'selected':''}>This month</option><option value="year" ${ui.activityRange==='year'?'selected':''}>This year</option></select><button class="secondary-button full" data-action="clear-filters">Clear filters</button><div class="section-head"><h2>Export</h2></div><button class="secondary-button full" data-action="export-csv">Download CSV</button></aside></div></section>`}
function pageInsights(){const s=stats(),cats=categorySpend(),max=Math.max(1,...cats.map(c=>c.amount)),goals=state.goals.map(g=>({g,p:goalProgress(g)}));return `<section class="page">${header('Insights','Your data, made useful')}<div class="insight-grid"><section class="panel"><div class="section-head"><h2>Spending by category</h2><span class="small-copy">This month</span></div><div class="bar-list">${cats.length?cats.map(c=>`<div class="bar-row"><span class="bar-label">${category(c.categoryId).icon} ${esc(category(c.categoryId).name)}</span><div class="bar"><i style="width:${Math.max(2,c.amount/max*100)}%"></i></div><strong>${money(c.amount)}</strong></div>`).join(''):empty('No spending data','Expenses will appear here after you add them.')}</div></section><section class="panel"><h3>Cash flow</h3><div class="report-stats"><div class="metric"><label>Income</label><strong class="positive">${money(s.income)}</strong></div><div class="metric"><label>Expenses</label><strong class="negative">${money(s.expenses)}</strong></div><div class="metric"><label>Net cash flow</label><strong class="${s.net>=0?'positive':'negative'}">${money(s.net)}</strong></div><div class="metric"><label>Planned bills</label><strong>${money(s.commitments)}</strong></div></div><div class="section-head"><h2>Goals</h2><button class="text-button" data-action="manage-goals">Manage</button></div><div class="bar-list">${goals.length?goals.map(x=>`<div class="bar-row"><span class="bar-label">${esc(x.g.name)}</span><div class="bar"><i style="width:${x.p.percent}%"></i></div><strong>${Math.round(x.p.percent)}%</strong></div>`).join(''):empty('No goals yet','Create a goal to track savings without changing your cash flow.','manage-goals','Create goal')}</div></section></div><div class="insight-grid"><section class="panel"><div class="section-head"><h2>Accounts</h2><button class="text-button" data-action="manage-accounts">Manage</button></div><div class="list">${state.accounts.length?state.accounts.map(a=>`<article class="transaction"><div class="category-dot">◒</div><div class="transaction-info"><div class="transaction-title">${esc(a.name)}</div><div class="transaction-meta">${esc(a.type||'Account')}</div></div><div class="amount">${money(accountBalance(a.id))}</div></article>`).join(''):empty('No accounts','Add an account before recording transactions.','manage-accounts','Add account')}</div></section><section class="panel"><div class="section-head"><h2>Debt position</h2><button class="text-button" data-action="manage-debts">Manage</button></div><div class="report-stats"><div class="metric"><label>Owed to you</label><strong class="positive">${money(debtsSummary().lent)}</strong></div><div class="metric"><label>You owe</label><strong class="negative">${money(debtsSummary().borrowed)}</strong></div></div></section></div></section>`}
function pageSettings(){const p=profile();return `<section class="page">${header('Settings','Your private workspace')}<div class="settings-grid"><section class="panel setting-section"><h3>Profile & appearance</h3><p>Personalise your on-device workspace. Your name and color never leave this browser.</p><div class="settings-actions"><button class="secondary-button" data-action="edit-profile">Edit profile</button><button class="secondary-button" data-action="toggle-hide">${p.hideBalances?'Show amounts':'Hide amounts'}</button><button class="secondary-button" data-action="replay-tour">Replay tour</button></div></section><section class="panel setting-section"><h3>Finance setup</h3><p>Manage the building blocks your records use.</p><div class="settings-actions"><button class="secondary-button" data-action="manage-accounts">Accounts</button><button class="secondary-button" data-action="manage-categories">Categories</button><button class="secondary-button" data-action="manage-budget">Budgets</button><button class="secondary-button" data-action="manage-debts">Debts</button><button class="secondary-button" data-action="manage-goals">Goals</button><button class="secondary-button" data-action="manage-reminders">Reminders</button></div></section><section class="panel setting-section"><h3>Local alerts</h3><p>Alerts are evaluated when you open Pocketwise. Browser notifications require permission and may not run in the background.</p><label class="toggle-row"><span>Budget warning</span><input class="toggle" type="checkbox" data-setting="budgetWarnings" ${state.settings.budgetWarnings?'checked':''}></label><label class="toggle-row"><span>Bill reminders</span><input class="toggle" type="checkbox" data-setting="billAlerts" ${state.settings.billAlerts?'checked':''}></label><label class="toggle-row"><span>Positive goal feedback</span><input class="toggle" type="checkbox" data-setting="positiveAlerts" ${state.settings.positiveAlerts?'checked':''}></label><div class="settings-actions" style="margin-top:14px"><button class="secondary-button" data-action="notification-permission">Request browser permission</button><button class="secondary-button" data-action="persistent-storage">Protect local storage</button></div></section><section class="panel setting-section"><h3>Data & privacy</h3><p>Records are stored locally on this device. Anyone with access to this browser profile may be able to see them. Clearing browser data or losing this device can remove records—keep a backup.</p><div class="settings-actions"><button class="secondary-button" data-action="export-backup">Export backup</button><button class="secondary-button" data-action="restore-trigger">Restore or merge</button><input id="restore-file" type="file" accept="application/json" hidden><button class="danger-button" data-action="reset">Reset workspace</button></div></section></div></section>`}
function assistantMessage(message,who){return `<div class="message ${who==='user'?'user':''}"><div class="message-avatar">${who==='user'?esc(profile().name).slice(0,1).toUpperCase():'✦'}</div><div class="message-content">${message}</div></div>`}
function pageAssistant(){const p=profile();const conversation=ui.assistant.length?ui.assistant.map(m=>assistantMessage(m.text,m.who)).join(''):assistantMessage(`<p>I can read the financial records stored in this browser and turn them into straightforward answers. I’m not a remote AI service, and I won’t invent financial information.</p>`,'assistant');return `<section class="page assistant-page"><div class="assistant-head">${header('', 'Pocketwise assistant')}</div><div class="assistant-welcome"><p>Hi, ${esc(p.name)}.</p><h1>How can I help with <em>your money?</em></h1><p class="assistant-disclaimer">Try a question or use a shortcut. Answers are based only on your saved Pocketwise records.</p></div><div class="suggestions"><button class="suggestion" data-action="assistant-suggestion" data-prompt="How much did I spend this month?"><b>Monthly spending</b><small>See recorded spending now</small></button><button class="suggestion" data-action="assistant-suggestion" data-prompt="Show upcoming bills"><b>Upcoming bills</b><small>Review planned commitments</small></button><button class="suggestion" data-action="assistant-suggestion" data-prompt="Add a new expense"><b>Add an expense</b><small>Open a reviewed record form</small></button><button class="suggestion" data-action="assistant-suggestion" data-prompt="How much can I save?"><b>Available to save</b><small>Use today’s local balance</small></button></div><div class="conversation" id="conversation">${conversation}</div><form class="assistant-composer" id="assistant-form"><textarea id="assistant-input" rows="1" placeholder="Ask about your finances…" aria-label="Assistant message"></textarea><button class="send" id="assistant-send" aria-label="Send message" disabled>↑</button></form></section>`}
function render(){applyShape();if(document.documentElement)document.documentElement.dataset.theme=state.settings.theme||'dark';let content=ui.page==='home'?pageHome():ui.page==='activity'?pageActivity():ui.page==='insights'?pageInsights():ui.page==='assistant'?pageAssistant():pageSettings();$('#app').innerHTML=layout(content);if(ui.page==='assistant'){const c=$('#conversation');if(c)c.scrollTop=c.scrollHeight;const input=$('#assistant-input');input?.focus();}}
function openModal(body){const modal=$('#modal');modal.innerHTML=body;modal.showModal();return modal}
function closeModal(){if($('#modal').open)$('#modal').close()}
function modalHead(title,copy=''){return `<div class="modal-head"><div><h2>${title}</h2>${copy?'<p>'+copy+'</p>':''}</div><button class="close" data-action="close-modal" aria-label="Close">×</button></div>`}
function accountOptions(selected='',exclude=''){return state.accounts.filter(a=>a.id!==exclude).map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${rawMoney(accountBalance(a.id))}</option>`).join('')}
function categoryOptions(selected=''){return state.categories.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.icon} ${esc(c.name)}</option>`).join('')}
function transactionForm(tx=null,forceType=''){const edit=!!tx;const data=tx||{type:forceType||'expense',amount:'',date:today(),categoryId:'food',accountId:state.accounts[0]?.id||'',sourceAccountId:state.accounts[0]?.id||'',destinationAccountId:state.accounts[1]?.id||'',note:''};const noAccounts=!state.accounts.length;const transfer=data.type==='transfer';const debtTypes=['debtLent','debtBorrowed','debtReceived','debtPaid'];return openModal(`<div class="modal-inner">${modalHead(edit?'Edit transaction':'Add transaction',noAccounts?'Add an account first—records always need a real account.':'Review details before saving; all calculations update together.')}<form id="transaction-form"><input type="hidden" name="id" value="${data.id||''}"><div class="form-grid"><div class="form-field"><label for="txn-type">Type</label><select id="txn-type" name="type"><option value="expense" ${data.type==='expense'?'selected':''}>Expense</option><option value="income" ${data.type==='income'?'selected':''}>Income</option><option value="transfer" ${transfer?'selected':''}>Transfer</option><option value="refund" ${data.type==='refund'?'selected':''}>Refund</option><option value="debtLent" ${data.type==='debtLent'?'selected':''}>Money lent</option><option value="debtBorrowed" ${data.type==='debtBorrowed'?'selected':''}>Money borrowed</option><option value="debtReceived" ${data.type==='debtReceived'?'selected':''}>Debt repayment received</option><option value="debtPaid" ${data.type==='debtPaid'?'selected':''}>Debt repayment made</option></select></div><div class="form-field"><label>Amount (INR)</label><input name="amount" type="number" step="0.01" min="0.01" required value="${esc(data.amount)}" placeholder="0.00"></div><div class="form-field"><label>Date</label><input name="date" type="date" required value="${esc(data.date)}"></div><div class="form-field" data-txn-category><label>Category / activity</label><select name="categoryId">${categoryOptions(data.categoryId)}</select></div><div class="form-field" data-txn-account><label>${transfer?'From account':'Account'}</label><select name="accountId">${accountOptions(transfer?data.sourceAccountId:data.accountId)}</select></div><div class="form-field" data-txn-destination style="display:${transfer?'grid':'none'}"><label>To account</label><select name="destinationAccountId">${accountOptions(data.destinationAccountId,transfer?data.sourceAccountId:'')}</select></div><div class="form-field wide"><label>Note (optional)</label><textarea name="note" placeholder="What was this for?">${esc(data.note)}</textarea></div></div><div class="form-error" id="transaction-error"></div><div class="form-foot"><button type="button" class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" ${noAccounts?'disabled':''}>${edit?'Save changes':'Save record'}</button></div></form></div>`)}
async function saveTransaction(form){const fd=new FormData(form);const tx={id:fd.get('id')||id('tx'),type:fd.get('type'),amount:num(fd.get('amount')),date:fd.get('date'),categoryId:fd.get('categoryId'),accountId:fd.get('accountId'),sourceAccountId:fd.get('accountId'),destinationAccountId:fd.get('destinationAccountId'),note:String(fd.get('note')||'').trim(),createdAt:Date.now()};const error=$('#transaction-error',form);if(!tx.amount||tx.amount<=0||!tx.date||!tx.accountId){error.textContent='Enter a positive amount, date, and account.';return}if(tx.type==='transfer'&&(!tx.destinationAccountId||tx.destinationAccountId===tx.sourceAccountId)){error.textContent='Choose two different accounts for a transfer.';return}if(tx.type==='transfer')tx.categoryId='other';const old=state.transactions.find(x=>x.id===tx.id);if(old)tx.createdAt=old.createdAt;await mutate(()=>{const index=state.transactions.findIndex(x=>x.id===tx.id);if(index>=0)state.transactions[index]=tx;else state.transactions.push(tx)},old?'Transaction updated.':'Transaction saved.');closeModal()}
function transactionDetail(tx){const c=category(tx.categoryId);const details=[['Type',typeName(tx.type)],['Amount',rawMoney(tx.amount)],['Date',dateLabel(tx.date)],['Account',tx.type==='transfer'?accountName(tx.sourceAccountId)+' → '+accountName(tx.destinationAccountId):accountName(tx.accountId)],['Category',c.icon+' '+c.name],['Note',tx.note||'—']];openModal(`<div class="modal-inner">${modalHead('Transaction details','This record updates every summary and account balance.')}<div class="detail-list">${details.map(d=>`<div class="detail-line"><span>${d[0]}</span><b>${esc(d[1])}</b></div>`).join('')}</div><div class="form-foot"><button class="danger-button" data-action="delete-transaction" data-id="${tx.id}">Delete</button><button class="secondary-button" data-action="edit-transaction" data-id="${tx.id}">Edit</button></div></div>`)}
function profileForm(){const p=profile();openModal(`<div class="modal-inner">${modalHead('Your profile','Stored only in this local workspace.')}<form id="profile-form"><div class="form-grid"><div class="form-field wide"><label>Display name</label><input name="name" required maxlength="32" value="${esc(p.name)}"></div><div class="form-field wide"><label>Avatar colour</label><div class="colour-options">${['#735ef7','#be77ff','#3c9ed6','#e07d72','#61b991'].map(color=>`<label style="background:${color}"><input type="radio" name="avatar" value="${color}" ${p.avatar===color?'checked':''}></label>`).join('')}</div></div></div><div class="form-error" id="profile-error"></div><div class="form-foot"><button class="secondary-button" type="button" data-action="close-modal">Cancel</button><button class="primary-button">Save profile</button></div></form></div>`)}
function accountManager(){const rows=state.accounts.map(a=>`<div class="management-row"><div class="category-dot">◒</div><div class="grow"><b>${esc(a.name)}</b><small>${esc(a.type||'Other')} · opening ${rawMoney(a.openingBalance)}</small></div><b>${money(accountBalance(a.id))}</b><button class="small-button" data-action="edit-account" data-id="${a.id}">Edit</button><button class="small-button" data-action="delete-account" data-id="${a.id}">Delete</button></div>`).join('');openModal(`<div class="modal-inner">${modalHead('Accounts','Balances are calculated from opening amounts and saved transactions.')}<div class="modal-list">${rows||empty('No accounts','Create one before you record income, expenses, or transfers.')}</div><div class="form-foot"><button class="secondary-button" data-action="new-account">Add account</button></div></div>`)}
function accountForm(acc=null){openModal(`<div class="modal-inner">${modalHead(acc?'Edit account':'Add account','An account can be removed only after its records have been resolved.')}<form id="account-form"><input type="hidden" name="id" value="${acc?.id||''}"><div class="form-grid"><div class="form-field"><label>Account name</label><input name="name" required maxlength="40" value="${esc(acc?.name||'')}"></div><div class="form-field"><label>Account type</label><select name="type">${['Cash','Bank / UPI','Card','Savings','Other'].map(x=>`<option ${(acc?.type||'Bank / UPI')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field wide"><label>Opening balance (INR)</label><input name="openingBalance" type="number" step="0.01" value="${acc?.openingBalance??0}"></div></div><div class="form-error" id="account-error"></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-accounts">Cancel</button><button class="primary-button">Save account</button></div></form></div>`)}
function categoryManager(){const rows=state.categories.map(c=>`<div class="management-row"><div class="category-dot">${c.icon}</div><div class="grow"><b>${esc(c.name)}</b><small>${c.kind} ${c.archived?'· archived':''}</small></div><button class="small-button" data-action="toggle-category" data-id="${c.id}">${c.archived?'Restore':'Archive'}</button></div>`).join('');openModal(`<div class="modal-inner">${modalHead('Activities & categories','Archived categories stay attached to historical records.')}<div class="modal-list">${rows}</div><div class="form-foot"><button class="secondary-button" data-action="new-category">Add category</button></div></div>`)}
function categoryForm(){openModal(`<div class="modal-inner">${modalHead('Add category')}<form id="category-form"><div class="form-grid"><div class="form-field"><label>Name</label><input name="name" required maxlength="32"></div><div class="form-field"><label>Used for</label><select name="kind"><option value="expense">Expenses</option><option value="income">Income</option><option value="both">Both</option></select></div><div class="form-field wide"><label>Icon</label><input name="icon" maxlength="4" value="•"></div></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-categories">Cancel</button><button class="primary-button">Add category</button></div></form></div>`)}
function budgetManager(){const s=stats();const catRows=Object.entries(state.budget.categoryLimits||{}).map(([cid,limit])=>{const spend=categorySpend().find(x=>x.categoryId===cid)?.amount||0;return `<div class="management-row"><div class="grow"><b>${esc(category(cid).name)}</b><small>${rawMoney(spend)} spent of ${rawMoney(limit)}</small></div><button class="small-button" data-action="remove-category-budget" data-id="${cid}">Remove</button></div>`}).join('');openModal(`<div class="modal-inner">${modalHead('Budgets','Only recorded expenses, minus refunds, are counted.')}<form id="budget-form"><div class="form-grid"><div class="form-field wide"><label>Monthly spending limit (INR)</label><input name="monthlyLimit" type="number" min="0" step="0.01" value="${state.budget.monthlyLimit||''}" placeholder="Optional"></div><div class="form-field"><label>Warning at (%)</label><input name="warningThreshold" type="number" min="1" max="100" value="${state.settings.warningThreshold}"></div><div class="form-field"><label>Category limit for</label><select name="categoryId"><option value="">Choose a category</option>${categoryOptions()}</select></div><div class="form-field wide"><label>Category limit (INR)</label><input name="categoryLimit" type="number" min="0" step="0.01" placeholder="Leave blank to keep unchanged"></div></div><div class="form-error" id="budget-error"></div><div class="form-foot"><button class="primary-button">Save budget</button></div></form><div class="section-head"><h2>Category budgets</h2><span class="small-copy">${money(s.expenses)} recorded</span></div><div class="modal-list">${catRows||empty('No category limits','Add a limit using the fields above.')}</div></div>`)}
function debtManager(){const rows=state.debts.map(d=>{const outstanding=debtOutstanding(d);return `<div class="management-row"><div class="category-dot">${d.direction==='lent'?'↗':'↙'}</div><div class="grow"><b>${esc(d.person)}</b><small>${d.direction==='lent'?'Owed to you':'You owe'} · ${d.expectedDate?'due '+dateLabel(d.expectedDate):'no due date'}</small></div><b class="${d.direction==='lent'?'positive':'negative'}">${money(outstanding)}</b>${outstanding?'<button class="small-button" data-action="repay-debt" data-id="'+d.id+'">Repay</button>':''}</div>`}).join('');openModal(`<div class="modal-inner">${modalHead('Debts & lending','Repayments are linked to the original record and excluded from income and spending reports.')}<div class="modal-list">${rows||empty('No debts yet','Track money you lent or borrowed here.')}</div><div class="form-foot"><button class="secondary-button" data-action="new-debt">Add debt</button></div></div>`)}
function debtForm(){openModal(`<div class="modal-inner">${modalHead('Track a debt','Choose an account only if you want to record the initial money movement now.')}<form id="debt-form"><div class="form-grid"><div class="form-field"><label>Person</label><input name="person" required maxlength="50"></div><div class="form-field"><label>Direction</label><select name="direction"><option value="lent">I lent money</option><option value="borrowed">I borrowed money</option></select></div><div class="form-field"><label>Original amount (INR)</label><input name="amount" type="number" step="0.01" min="0.01" required></div><div class="form-field"><label>Date</label><input name="date" type="date" value="${today()}" required></div><div class="form-field"><label>Expected repayment date</label><input name="expectedDate" type="date"></div><div class="form-field"><label>Account (optional)</label><select name="accountId"><option value="">Do not record money movement</option>${accountOptions()}</select></div><div class="form-field wide"><label>Note</label><textarea name="note"></textarea></div></div><div class="form-error" id="debt-error"></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-debts">Cancel</button><button class="primary-button">Save debt</button></div></form></div>`)}
function repaymentForm(debt){openModal(`<div class="modal-inner">${modalHead('Record repayment',esc(debt.person)+' has '+rawMoney(debtOutstanding(debt))+' outstanding.')}<form id="repayment-form"><input type="hidden" name="debtId" value="${debt.id}"><div class="form-grid"><div class="form-field"><label>Amount (INR)</label><input name="amount" type="number" min="0.01" max="${debtOutstanding(debt)}" step="0.01" required></div><div class="form-field"><label>Date</label><input name="date" type="date" value="${today()}" required></div><div class="form-field wide"><label>Account</label><select name="accountId">${accountOptions()}</select></div></div><div class="form-error" id="repayment-error"></div><div class="form-foot"><button class="secondary-button" type="button" data-action="manage-debts">Cancel</button><button class="primary-button">Save repayment</button></div></form></div>`)}
function goalManager(){const rows=state.goals.map(g=>{const p=goalProgress(g);return `<div class="management-row"><div class="category-dot">★</div><div class="grow"><b>${esc(g.name)}</b><small>${rawMoney(p.saved)} saved of ${rawMoney(p.target)}</small><div class="progress-track" style="margin-top:6px"><b style="width:${p.percent}%"></b></div></div><button class="small-button" data-action="contribute-goal" data-id="${g.id}">Add</button></div>`}).join('');openModal(`<div class="modal-inner">${modalHead('Savings goals','Contributions track progress only and never create income or spending.')}<div class="modal-list">${rows||empty('No goals yet','Create a goal to track a planned saving target.')}</div><div class="form-foot"><button class="secondary-button" data-action="new-goal">Add goal</button></div></div>`)}
function goalForm(){openModal(`<div class="modal-inner">${modalHead('Create savings goal')}<form id="goal-form"><div class="form-grid"><div class="form-field"><label>Goal name</label><input name="name" required maxlength="50"></div><div class="form-field"><label>Target amount (INR)</label><input name="target" type="number" min="0.01" step="0.01" required></div><div class="form-field wide"><label>Already saved (optional)</label><input name="initialAmount" type="number" min="0" step="0.01" value="0"></div></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-goals">Cancel</button><button class="primary-button">Save goal</button></div></form></div>`)}
function contributionForm(goal){openModal(`<div class="modal-inner">${modalHead('Add goal contribution',esc(goal.name)+' has '+rawMoney(goalProgress(goal).target-goalProgress(goal).saved)+' left to reach its target.')}<form id="contribution-form"><input type="hidden" name="goalId" value="${goal.id}"><div class="form-grid"><div class="form-field"><label>Amount (INR)</label><input name="amount" type="number" step="0.01" min="0.01" required></div><div class="form-field"><label>Date</label><input name="date" type="date" value="${today()}" required></div></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-goals">Cancel</button><button class="primary-button">Add contribution</button></div></form></div>`)}
function reminderManager(){const rows=state.reminders.map(r=>{const due=nextDue(r);return `<div class="management-row"><div class="category-dot">◷</div><div class="grow"><b>${esc(r.description)}</b><small>${rawMoney(r.amount)} · ${r.recurrence} · next ${dateLabel(due)}</small></div><button class="small-button" data-action="pay-reminder" data-id="${r.id}">Pay</button><button class="small-button" data-action="delete-reminder" data-id="${r.id}">Delete</button></div>`}).join('');openModal(`<div class="modal-inner">${modalHead('Reminders & planned payments','A reminder does not change your balance until you record a real transaction.')}<div class="modal-list">${rows||empty('No reminders','Create recurring bills, subscriptions, or planned payments.')}</div><div class="form-foot"><button class="secondary-button" data-action="new-reminder">Add reminder</button></div></div>`)}
function reminderForm(){openModal(`<div class="modal-inner">${modalHead('Add reminder','Monthly dates adjust safely when a month has fewer days.')}<form id="reminder-form"><div class="form-grid"><div class="form-field"><label>Description</label><input name="description" required maxlength="60"></div><div class="form-field"><label>Amount (INR)</label><input name="amount" type="number" step="0.01" min="0.01" required></div><div class="form-field"><label>First due date</label><input name="date" type="date" value="${today()}" required></div><div class="form-field"><label>Repeat</label><select name="recurrence"><option value="once">Once</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select></div><div class="form-field wide"><label>Default account (optional)</label><select name="accountId"><option value="">Choose when paying</option>${accountOptions()}</select></div></div><div class="form-foot"><button type="button" class="secondary-button" data-action="manage-reminders">Cancel</button><button class="primary-button">Save reminder</button></div></form></div>`)}
function moreActions(){openModal(`<div class="modal-inner">${modalHead('More ways to manage money')}<div class="settings-actions"><button class="secondary-button" data-action="manage-debts">Debts & lending</button><button class="secondary-button" data-action="manage-goals">Savings goals</button><button class="secondary-button" data-action="manage-reminders">Reminders</button><button class="secondary-button" data-action="manage-accounts">Accounts</button><button class="secondary-button" data-action="manage-categories">Categories</button></div></div>`)}
function showTour(step=0){const screens=[['Welcome to Pocketwise','Keep a calm overview of real financial records—without needing an account or cloud login.'],['Record with confidence','Income, expenses, transfers, refunds, debt activity, and account balances all use the same calculations.'],['Your data stays local','Export JSON backups regularly. This browser cannot guarantee protection if someone else can access your unlocked device.']];const item=screens[step];const t=$('#tour');t.innerHTML=`<div class="modal-inner tour-step"><span class="tour-number">${step+1} of ${screens.length}</span><h2>${item[0]}</h2><p>${item[1]}</p><div class="tour-actions"><div class="tour-dots">${screens.map((_,i)=>'<i class="'+(i===step?'active':'')+'"></i>').join('')}</div><div>${step<screens.length-1?'<button class="secondary-button" data-action="close-tour">Skip</button> <button class="primary-button" data-action="tour-next" data-step="'+step+'">Next</button>':'<button class="primary-button" data-action="close-tour">Get started</button>'}</div></div></div>`;t.showModal()}
function onboarding(){openModal(`<div class="modal-inner">${modalHead('Welcome to Pocketwise','A private finance workspace that starts on this device.')}<form id="onboarding-form"><div class="form-grid"><div class="form-field wide"><label>What should we call you?</label><input name="name" required maxlength="32" placeholder="Your name" autofocus></div><div class="form-field wide"><label>Avatar colour</label><div class="colour-options">${['#735ef7','#be77ff','#3c9ed6','#e07d72','#61b991'].map((color,i)=>`<label style="background:${color}"><input type="radio" name="avatar" value="${color}" ${i===0?'checked':''}></label>`).join('')}</div></div><div class="form-field wide"><label><input type="checkbox" name="sample"> Load clearly marked example records to explore the app</label></div></div><p class="small-copy">You can create accounts and add data yourself at any time. Nothing is sent to Pocketwise.</p><div class="form-foot"><button class="primary-button">Create local workspace</button></div></form></div>`)}
function sampleWorkspace(){const cash={id:id('acc'),name:'Cash wallet',type:'Cash',openingBalance:1800};const bank={id:id('acc'),name:'Everyday bank',type:'Bank / UPI',openingBalance:12500};state.accounts=[cash,bank];const m=monthKey();state.transactions=[{id:id('tx'),type:'income',amount:48000,date:m+'-01',categoryId:'salary',accountId:bank.id,note:'Example salary',createdAt:1},{id:id('tx'),type:'expense',amount:840,date:m+'-03',categoryId:'food',accountId:cash.id,note:'Example grocery run',createdAt:2},{id:id('tx'),type:'expense',amount:1299,date:m+'-05',categoryId:'bills',accountId:bank.id,note:'Example subscription',createdAt:3},{id:id('tx'),type:'transfer',amount:1500,date:m+'-06',categoryId:'other',accountId:bank.id,sourceAccountId:bank.id,destinationAccountId:cash.id,note:'Example cash top-up',createdAt:4}];state.budget.monthlyLimit=18000;state.goals=[{id:id('goal'),name:'Emergency cushion',target:30000,initialAmount:8000,contributions:[]}];state.reminders=[{id:id('rem'),description:'Example mobile plan',amount:599,date:m+'-26',recurrence:'monthly',accountId:bank.id}];state.sampleData=true}
function toast(message,type=''){const t=document.createElement('div');t.className='toast '+type;t.textContent=message;$('#toast-region').append(t);setTimeout(()=>t.remove(),3800)}
function download(filename,contents,type){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvSafe(value){let v=String(value??'');if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
function exportCSV(){const fields=['id','date','type','amountINR','activity','sourceAccount','destinationAccount','debtPerson','note'];const rows=state.transactions.map(t=>[t.id,t.date,t.type,t.amount,txTitle(t),t.type==='transfer'?accountName(t.sourceAccountId):accountName(t.accountId),t.type==='transfer'?accountName(t.destinationAccountId):'',state.debts.find(d=>d.id===t.debtId)?.person||'',t.note]);download('pocketwise-transactions-'+today()+'.csv',[fields,...rows].map(r=>r.map(csvSafe).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Transaction CSV exported.','success')}
function exportBackup(){const backup={format:'pocketwise-backup',version:APP_VERSION,exportedAt:new Date().toISOString(),workspace:state};download('pocketwise-backup-'+today()+'.json',JSON.stringify(backup,null,2),'application/json');toast('Full local backup exported.','success')}
async function importBackup(file){try{const parsed=JSON.parse(await file.text());if(parsed.format!=='pocketwise-backup'||!parsed.workspace||!Array.isArray(parsed.workspace.transactions)||!Array.isArray(parsed.workspace.accounts))throw new Error('not valid');const merge=confirm('Press OK to merge this backup with records here. Press Cancel to replace your entire current workspace.');if(merge){const incoming=parsed.workspace;for(const key of ['accounts','categories','transactions','debts','goals','reminders']){const seen=new Set(state[key].map(x=>x.id));state[key].push(...(incoming[key]||[]).filter(x=>x?.id&&!seen.has(x.id)))}state.budget={...state.budget,...(incoming.budget||{})};state.settings={...state.settings,...(incoming.settings||{})}}else{if(!confirm('Replace all current Pocketwise data with this backup? This cannot be undone without another backup.'))return;state=parsed.workspace;applyShape()}await persist();render();toast(merge?'Backup merged without duplicate IDs.':'Backup restored.','success')}catch{toast('That file is not a valid Pocketwise backup.','error')}}
function assistantReply(prompt){const q=prompt.toLowerCase(),s=stats(),future=state.reminders.map(r=>({...r,due:nextDue(r)})).sort((a,b)=>a.due.localeCompare(b.due));if(/add.*(expense|spend)|new expense/.test(q)){setTimeout(()=>transactionForm(null,'expense'),100);return `<p>I opened a reviewed expense form. Nothing will be saved until you confirm it.</p>`}if(/add.*income/.test(q)){setTimeout(()=>transactionForm(null,'income'),100);return `<p>I opened a reviewed income form. Nothing will be saved until you confirm it.</p>`}if(/spend|expense/.test(q))return `<p>This month, your recorded spending is <b>${money(s.expenses)}</b> across ${monthTransactions().filter(t=>t.type==='expense').length} expense record(s).${s.limit?' Your budget has '+money(s.remaining)+' remaining.':''}</p>`;if(/upcoming|bill|reminder/.test(q))return future.length?`<p>Your next planned payment is <b>${esc(future[0].description)}</b>: ${money(future[0].amount)} on ${dateLabel(future[0].due)}. Planned payments do not affect your balance until you record them.</p>`:`<p>You do not have any saved reminders. You can add one from Settings → Reminders.</p>`;if(/save|available|afford/.test(q))return `<p>Your current account balance is <b>${money(totalBalance())}</b>. After this month’s saved planned commitments, the dashboard estimates <b>${money(s.available)}</b> available to spend. This is an estimate, not financial advice.</p>`;if(/income|cash flow/.test(q))return `<p>This month: income <b>${money(s.income)}</b>, spending <b>${money(s.expenses)}</b>, and net cash flow <b>${money(s.net)}</b>.</p>`;return `<p>I can answer from records saved in Pocketwise: try “How much did I spend this month?”, “Show upcoming bills”, “How much can I save?”, or “Add a new expense”.</p>`}
function sendAssistant(text){const prompt=String(text||'').trim();if(!prompt)return;ui.assistant.push({who:'user',text:`<p>${esc(prompt)}</p>`});ui.assistant.push({who:'assistant',text:assistantReply(prompt)});render()}
async function handleAction(action,el){const ident=el.dataset.id;switch(action){case 'close-modal':closeModal();break;case 'close-tour':$('#tour').close();break;case 'tour-next':$('#tour').close();showTour(Number(el.dataset.step)+1);break;case 'replay-tour':showTour();break;case 'toggle-hide':await mutate(()=>state.profile.hideBalances=!state.profile.hideBalances);break;case 'quick-add':transactionForm();break;case 'add-expense':transactionForm(null,'expense');break;case 'add-income':transactionForm(null,'income');break;case 'transfer':transactionForm(null,'transfer');break;case 'more-actions':moreActions();break;case 'chart-period':ui.chartPeriod=el.dataset.period;render();break;case 'voice-note':{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice recognition is unavailable here. You can use your keyboard or device microphone instead.','error');break}const recognizer=new Recognition();recognizer.lang='en-IN';recognizer.interimResults=false;recognizer.onresult=e=>{const spoken=e.results[0][0].transcript;const note=$('[name=\"note\"]');if(note)note.value=spoken;const found=spoken.match(/(?:₹|rs\.?|rupees?)?\s*(\d+(?:\.\d{1,2})?)/i);const amount=$('[name=\"amount\"]');if(found&&amount&&!amount.value)amount.value=found[1];toast('Voice draft added. Review every field before saving.','success')};recognizer.onerror=()=>toast('Voice entry was not available. Use the manual form instead.','error');recognizer.start();break;}case 'transaction-detail':transactionDetail(state.transactions.find(t=>t.id===ident));break;case 'edit-transaction':transactionForm(state.transactions.find(t=>t.id===ident));break;case 'delete-transaction':if(confirm('Delete this transaction? Its effects will be removed from every calculation.')){await mutate(()=>state.transactions=state.transactions.filter(t=>t.id!==ident),'Transaction deleted.');closeModal()}break;case 'clear-filters':ui.activityType='all';ui.activityRange='all';ui.activitySearch='';render();break;case 'export-csv':exportCSV();break;case 'edit-profile':profileForm();break;case 'manage-accounts':accountManager();break;case 'new-account':accountForm();break;case 'edit-account':accountForm(account(ident));break;case 'delete-account':{const used=state.transactions.some(t=>t.accountId===ident||t.sourceAccountId===ident||t.destinationAccountId===ident);if(used){toast('Resolve or move this account’s transactions before removing it.','error');break}if(confirm('Remove this empty account?'))await mutate(()=>state.accounts=state.accounts.filter(a=>a.id!==ident),'Account removed.');accountManager();break}case 'manage-categories':categoryManager();break;case 'new-category':categoryForm();break;case 'toggle-category':await mutate(()=>{const c=category(ident);c.archived=!c.archived},'Category updated.');categoryManager();break;case 'manage-budget':budgetManager();break;case 'remove-category-budget':await mutate(()=>delete state.budget.categoryLimits[ident],'Category budget removed.');budgetManager();break;case 'manage-debts':debtManager();break;case 'new-debt':debtForm();break;case 'repay-debt':repaymentForm(state.debts.find(d=>d.id===ident));break;case 'manage-goals':goalManager();break;case 'new-goal':goalForm();break;case 'contribute-goal':contributionForm(state.goals.find(g=>g.id===ident));break;case 'manage-reminders':reminderManager();break;case 'new-reminder':reminderForm();break;case 'pay-reminder':{const r=state.reminders.find(x=>x.id===ident);transactionForm(null,'expense');setTimeout(()=>{const f=$('#transaction-form');if(f){f.amount.value=r.amount;f.date.value=nextDue(r);f.note.value='Payment: '+r.description;f.categoryId.value='bills';if(r.accountId)f.accountId.value=r.accountId}},0);break}case 'delete-reminder':if(confirm('Remove this reminder?'))await mutate(()=>state.reminders=state.reminders.filter(r=>r.id!==ident),'Reminder removed.');reminderManager();break;case 'notification-permission':if(!('Notification'in window)){toast('This browser does not support notifications.','error');break}try{const result=await Notification.requestPermission();toast(result==='granted'?'Browser notification permission granted.':'Notification permission was not granted.',result==='granted'?'success':'error')}catch{toast('Notification permission could not be requested.','error')}break;case 'persistent-storage':if(navigator.storage?.persist){const ok=await navigator.storage.persist();toast(ok?'Browser accepted persistent storage.':'Browser did not grant persistent storage.',ok?'success':'error')}else toast('This browser does not expose persistent storage controls.','error');break;case 'export-backup':exportBackup();break;case 'restore-trigger':$('#restore-file')?.click();break;case 'clear-sample':if(confirm('Clear all example accounts, records, budgets, goals, debts, and reminders while keeping your profile and preferences?')){await mutate(()=>{state.accounts=[];state.transactions=[];state.budget={monthlyLimit:0,categoryLimits:{}};state.debts=[];state.goals=[];state.reminders=[];state.sampleData=false},'Example data cleared.')}break;case 'reset':if(confirm('Reset all financial records, accounts, budgets, goals, debts, reminders, and profile? Export a backup first if you may need this data.')){state=freshState();await persist();ui={page:'home',activityType:'all',activityRange:'all',activitySearch:'',chartPeriod:'month',assistant:[]};render();onboarding();toast('Local workspace reset.','success')}break;case 'assistant-suggestion':sendAssistant(el.dataset.prompt);break;}}
document.addEventListener('click',e=>{const item=e.target.closest('[data-page]');if(item){ui.page=item.dataset.page;render();return}const action=e.target.closest('[data-action]');if(action)handleAction(action.dataset.action,action)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.closest('.transaction')){e.preventDefault();handleAction('transaction-detail',e.target.closest('.transaction'))}});
document.addEventListener('input',e=>{if(e.target.id==='activity-search'){ui.activitySearch=e.target.value;render()}if(e.target.id==='assistant-input'){$('#assistant-send').disabled=!e.target.value.trim();e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,110)+'px'}});
document.addEventListener('change',e=>{if(e.target.id==='activity-type'){ui.activityType=e.target.value;render()}if(e.target.id==='activity-range'){ui.activityRange=e.target.value;render()}if(e.target.dataset.setting==='theme-toggle'){state.settings.theme=e.target.checked?'dark':'light';persist();render();toast('Appearance saved.','success');return}if(e.target.matches('[data-setting]')){state.settings[e.target.dataset.setting]=e.target.checked;persist();toast('Preference saved.','success')}if(e.target.id==='restore-file'&&e.target.files?.[0])importBackup(e.target.files[0]);if(e.target.id==='txn-type'){const dest=$('[data-txn-destination]');if(dest)dest.style.display=e.target.value==='transfer'?'grid':'none';const accountLabel=$('[data-txn-account] label');if(accountLabel)accountLabel.textContent=e.target.value==='transfer'?'From account':'Account'}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='onboarding-form'){const fd=new FormData(form);state.profile={name:String(fd.get('name')).trim(),avatar:fd.get('avatar'),hideBalances:false};if(fd.get('sample'))sampleWorkspace();await persist();closeModal();render();showTour();toast('Your local workspace is ready.','success')}else if(form.id==='profile-form'){const fd=new FormData(form);const name=String(fd.get('name')).trim();if(!name){$('#profile-error',form).textContent='Please enter a display name.';return}await mutate(()=>state.profile={...state.profile,name,avatar:fd.get('avatar')},'Profile updated.');closeModal()}else if(form.id==='transaction-form')await saveTransaction(form);else if(form.id==='account-form'){const fd=new FormData(form),name=String(fd.get('name')).trim();if(!name){$('#account-error',form).textContent='Enter an account name.';return}const saved={id:fd.get('id')||id('acc'),name,type:fd.get('type'),openingBalance:num(fd.get('openingBalance'))};await mutate(()=>{const i=state.accounts.findIndex(a=>a.id===saved.id);if(i>=0)state.accounts[i]=saved;else state.accounts.push(saved)},'Account saved.');accountManager()}else if(form.id==='category-form'){const fd=new FormData(form),name=String(fd.get('name')).trim();if(!name)return;await mutate(()=>state.categories.push({id:id('cat'),name,icon:String(fd.get('icon')||'•').slice(0,4),kind:fd.get('kind')}),'Category added.');categoryManager()}else if(form.id==='budget-form'){const fd=new FormData(form),limit=fd.get('monthlyLimit');if(limit!==''&&num(limit)<0){$('#budget-error',form).textContent='Budget cannot be negative.';return}await mutate(()=>{state.budget.monthlyLimit=limit===''?0:num(limit);state.settings.warningThreshold=Math.min(100,Math.max(1,num(fd.get('warningThreshold'))||80));if(fd.get('categoryId')&&fd.get('categoryLimit')!=='')state.budget.categoryLimits[fd.get('categoryId')]=num(fd.get('categoryLimit'))},'Budget saved.');closeModal()}else if(form.id==='debt-form'){const fd=new FormData(form),amount=num(fd.get('amount'));if(!amount||amount<=0){$('#debt-error',form).textContent='Enter a positive amount.';return}const debt={id:id('debt'),person:String(fd.get('person')).trim(),direction:fd.get('direction'),amount,date:fd.get('date'),expectedDate:fd.get('expectedDate'),note:fd.get('note'),accountId:fd.get('accountId')};await mutate(()=>{state.debts.push(debt);if(debt.accountId)state.transactions.push({id:id('tx'),type:debt.direction==='lent'?'debtLent':'debtBorrowed',amount,date:debt.date,categoryId:'other',accountId:debt.accountId,debtId:debt.id,note:'Initial debt with '+debt.person,createdAt:Date.now()})},'Debt saved.');debtManager()}else if(form.id==='repayment-form'){const fd=new FormData(form),debt=state.debts.find(d=>d.id===fd.get('debtId')),amount=num(fd.get('amount'));if(!debt||!amount||amount>debtOutstanding(debt)){ $('#repayment-error',form).textContent='Enter an amount no greater than the outstanding balance.';return}await mutate(()=>state.transactions.push({id:id('tx'),type:debt.direction==='lent'?'debtReceived':'debtPaid',amount,date:fd.get('date'),categoryId:'other',accountId:fd.get('accountId'),debtId:debt.id,note:'Repayment: '+debt.person,createdAt:Date.now()}),'Repayment saved.');debtManager()}else if(form.id==='goal-form'){const fd=new FormData(form),target=num(fd.get('target'));if(!target)return;await mutate(()=>state.goals.push({id:id('goal'),name:String(fd.get('name')).trim(),target,initialAmount:num(fd.get('initialAmount')),contributions:[]}),'Goal created.');goalManager()}else if(form.id==='contribution-form'){const fd=new FormData(form),goal=state.goals.find(g=>g.id===fd.get('goalId')),amount=num(fd.get('amount'));if(!goal||!amount)return;await mutate(()=>goal.contributions.push({id:id('contribution'),amount,date:fd.get('date')}),'Goal contribution added.');goalManager()}else if(form.id==='reminder-form'){const fd=new FormData(form),amount=num(fd.get('amount'));if(!amount)return;await mutate(()=>state.reminders.push({id:id('reminder'),description:String(fd.get('description')).trim(),amount,date:fd.get('date'),recurrence:fd.get('recurrence'),accountId:fd.get('accountId')}),'Reminder saved.');reminderManager()}else if(form.id==='assistant-form'){sendAssistant($('#assistant-input').value)}});
function processShortcut(){if(typeof location==='undefined')return;const raw=new URLSearchParams(location.search).get('quickadd');if(!raw)return;try{const payload=JSON.parse(raw);if(!payload||!['expense','income','transfer','refund'].includes(payload.type)||!num(payload.amount))throw new Error('invalid');setTimeout(()=>transactionForm({id:payload.requestId||'',type:payload.type,amount:num(payload.amount),date:payload.date||today(),categoryId:payload.categoryId||'other',accountId:payload.accountId||state.accounts[0]?.id||'',sourceAccountId:payload.accountId||state.accounts[0]?.id||'',destinationAccountId:payload.destinationAccountId||'',note:String(payload.note||'')},payload.type),0);toast('Shortcut details loaded for review. Nothing has been saved.','success')}catch{toast('The quick-add payload could not be validated. Use the manual form instead.','error')}}
(async function init(){state=await storage.load();applyShape();render();if(!state.profile)onboarding();else processShortcut();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});})();
